const SPAM_NAME_PATTERNS = [
  /https?:\/\//i,
  /\bcasino\b/i,
  /\bviagra\b/i,
  /\bcrypto\b/i,
  /\bbitcoin\b/i,
  /\bseo\b/i,
  /\bclick here\b/i,
];

const DISPOSABLE_DOMAINS = new Set([
  "mailinator.com",
  "tempmail.com",
  "guerrillamail.com",
  "10minutemail.com",
  "yopmail.com",
  "throwaway.email",
  "trashmail.com",
]);

export function isSpamSubmission(payload: {
  name: string;
  phone: string;
  email?: string;
  message?: string;
}): string | null {
  const name = payload.name.trim();
  const message = (payload.message || "").trim();

  for (const pattern of SPAM_NAME_PATTERNS) {
    if (pattern.test(name) || pattern.test(message)) {
      return "Invalid submission.";
    }
  }

  if (message) {
    const linkCount = (message.match(/https?:\/\//gi) || []).length;
    if (linkCount > 1) return "Invalid submission.";
  }

  if (payload.email) {
    const domain = payload.email.split("@")[1]?.toLowerCase();
    if (domain && DISPOSABLE_DOMAINS.has(domain)) {
      return "Please use a regular email address.";
    }
  }

  const repeatedChar = /(.)\1{5,}/;
  if (repeatedChar.test(name.replace(/\s/g, ""))) {
    return "Invalid submission.";
  }

  return null;
}

import type { Metadata } from "next";
import { business } from "@/lib/business";

const siteName = business.name;

export function absoluteUrl(path = "/") {
  const base = business.siteUrl.replace(/\/$/, "");
  const clean = path.startsWith("/") ? path : `/${path}`;
  return `${base}${clean === "/" ? "" : clean}`;
}

export function buildMetadata({
  title,
  description,
  path = "/",
  image = "/images/gallery-modern-lawn.png",
  noIndex = false,
  keywords,
}: {
  title: string;
  description: string;
  path?: string;
  image?: string;
  noIndex?: boolean;
  keywords?: string[];
}): Metadata {
  const url = absoluteUrl(path);
  const fullTitle = title.includes(siteName) ? title : `${title} | ${siteName}`;
  const ogImage = absoluteUrl(image);

  return {
    title: { absolute: fullTitle },
    description,
    keywords: keywords?.length ? keywords : undefined,
    alternates: { canonical: url },
    robots: noIndex ? { index: false, follow: false } : { index: true, follow: true },
    openGraph: {
      type: "website",
      url,
      siteName,
      title: fullTitle,
      description,
      locale: "en_IN",
      images: [{ url: ogImage, width: 1200, height: 630, alt: fullTitle }],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage],
    },
  };
}

import { NextResponse } from "next/server";
import { sendLeadEmails } from "@/lib/leads/sendLeadEmail";
import { getClientIp, isRateLimited } from "@/lib/leads/rateLimit";
import { isSpamSubmission } from "@/lib/leads/spamGuard";
import { validateLeadPayload } from "@/lib/leads/validateLead";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const ip = getClientIp(request);
    if (isRateLimited(ip)) {
      return NextResponse.json(
        { ok: false, error: "Too many requests. Please call us directly." },
        { status: 429 }
      );
    }

    const body = await request.json();
    const parsed = validateLeadPayload(body);

    if (!parsed.ok) {
      return NextResponse.json({ ok: false, error: parsed.error }, { status: 400 });
    }

    if (parsed.data.honeypot) {
      return NextResponse.json({ ok: true });
    }

    const spamReason = isSpamSubmission(parsed.data);
    if (spamReason) {
      return NextResponse.json({ ok: false, error: spamReason }, { status: 400 });
    }

    await sendLeadEmails(parsed.data);
    return NextResponse.json({ ok: true });
  } catch (error) {
    console.error("[lead]", error);
    const msg = error instanceof Error ? error.message : "";
    const userMessage =
      msg.includes("RESEND_API_KEY")
        ? "Our contact form is temporarily unavailable. Please call us directly."
        : "We could not send your request right now. Please call us at +91 99901 16281.";
    return NextResponse.json({ ok: false, error: userMessage }, { status: 500 });
  }
}

import type { MetadataRoute } from "next";
import { blogPosts } from "@/content/blog/posts";
import { business } from "@/lib/business";
import { intentPages } from "@/lib/intent";
import { locations } from "@/lib/locations";
